2014279399724494850:
---
name: use-dom
description: Use Expo DOM components to run web code in a webview on native and as-is on web. Migrate web code to native incrementally.
version: 1.0.0
license: MIT
---

## What are DOM Components?

DOM components allow web code to run verbatim in a webview on native platforms while rendering as-is on web. This enables using web-only libraries like `recharts`, `react-syntax-highlighter`, or any React web library in your Expo app without modification.

## When to Use DOM Components

Use DOM components when you need:

- **Web-only libraries** — Charts (recharts, chart.js), syntax highlighters, rich text editors, or any library that depends on DOM APIs
- **Migrating web code** — Bring existing React web components to native without rewriting
- **Complex HTML/CSS layouts** — When CSS features aren't available in React Native
- **iframes or embeds** — Embedding external content that requires a browser context
- **Canvas or WebGL** — Web graphics APIs not available natively

## When NOT to Use DOM Components

Avoid DOM components when:

- **Native performance is critical** — Webviews add overhead
- **Simple UI** — React Native components are more efficient for basic layouts
- **Deep native integration** — Use local modules instead for native APIs
- **Layout routes** — `_layout` files cannot be DOM components

## Basic DOM Component

Create a new file with the `'use dom';` directive at the top:

```tsx
// components/WebChart.tsx
"use dom";

export default function WebChart({
  data,
}: {
  data: number[];
  dom: import("expo/dom").DOMProps;
}) {
  return (
    \u003cdiv style={{ padding: 20 }}\u003e
      \u003ch2\u003eChart Data\u003c/h2\u003e
      \u003cul\u003e
        {data.map((value, i) =\u003e (
          \u003cli key={i}\u003e{value}\u003c/li\u003e
        ))}
      \u003c/ul\u003e
    \u003c/div\u003e
  );
}
```

## Rules for DOM Components

1. **Must have `'use dom';` directive** at the top of the file
2. **Single default export** — One React component per file
3. **Own file** — Cannot be defined inline or combined with native components
4. **Serializable props only** — Strings, numbers, booleans, arrays, plain objects
5. **Include CSS in the component file** — DOM components run in isolated context

## The `dom` Prop

Every DOM component receives a special `dom` prop for webview configuration. Always type it in your props:

```tsx
"use dom";

interface Props {
  content: string;
  dom: import("expo/dom").DOMProps;
}

export default function MyComponent({ content }: Props) {
  return \u003cdiv\u003e{content}\u003c/div\u003e;
}
```

### Common `dom` Prop Options

```tsx
// Disable body scrolling
\u003cDOMComponent dom={{ scrollEnabled: false }} /\u003e

// Flow under the notch (disable safe area insets)
\u003cDOMComponent dom={{ contentInsetAdjustmentBehavior: "never" }} /\u003e

// Control size manually
\u003cDOMComponent dom={{ style: { width: 300, height: 400 } }} /\u003e

// Combine options
\u003cDOMComponent
  dom={{
    scrollEnabled: false,
    contentInsetAdjustmentBehavior: "never",
    style: { width: '100%', height: 500 }
  }}
/\u003e
```

## Exposing Native Actions to the Webview

Pass async functions as props to expose native functionality to the DOM component:

```tsx
// app/index.tsx (native)
import { Alert } from "react-native";
import DOMComponent from "@/components/dom-component";

export default function Screen() {
  return (
    \u003cDOMComponent
      showAlert={async (message: string) =\u003e {
        Alert.alert("From Web", message);
      }}
      saveData={async (data: { name: string; value: number }) =\u003e {
        // Save to native storage, database, etc.
        console.log("Saving:", data);
        return { success: true };
      }}
    /\u003e
  );
}
```

```tsx
// components/dom-component.tsx
"use dom";

interface Props {
  showAlert: (message: string) =\u003e Promise\u003cvoid\u003e;
  saveData: (data: {
    name: string;
    value: number;
  }) =\u003e Promise\u003c{ success: boolean }\u003e;
  dom?: import("expo/dom").DOMProps;
}

export default function DOMComponent({ showAlert, saveData }: Props) {
  const handleClick = async () =\u003e {
    await showAlert("Hello from the webview!");
    const result = await saveData({ name: "test", value: 42 });
    console.log("Save result:", result);
  };

  return \u003cbutton onClick={handleClick}\u003eTrigger Native Action\u003c/button\u003e;
}
```

## Using Web Libraries

DOM components can use any web library:

```tsx
// components/syntax-highlight.tsx
"use dom";

import SyntaxHighlighter from "react-syntax-highlighter";
import { docco } from "react-syntax-highlighter/dist/esm/styles/hljs";

interface Props {
  code: string;
  language: string;
  dom?: import("expo/dom").DOMProps;
}

export default function SyntaxHighlight({ code, language }: Props) {
  return (
    \u003cSyntaxHighlighter language={language} style={docco}\u003e
      {code}
    \u003c/SyntaxHighlighter\u003e
  );
}
```

```tsx
// components/chart.tsx
"use dom";

import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
} from "recharts";

interface Props {
  data: Array\u003c{ name: string; value: number }\u003e;
  dom: import("expo/dom").DOMProps;
}

export default function Chart({ data }: Props) {
  return (
    \u003cLineChart width={400} height={300} data={data}\u003e
      \u003cCartesianGrid strokeDasharray="3 3" /\u003e
      \u003cXAxis dataKey="name" /\u003e
      \u003cYAxis /\u003e
      \u003cTooltip /\u003e
      \u003cLine type="monotone" dataKey="value" stroke="#8884d8" /\u003e
    \u003c/LineChart\u003e
  );
}
```

## CSS in DOM Components

CSS imports must be in the DOM component file since they run in isolated context:

```tsx
// components/styled-component.tsx
"use dom";

import "@/styles.css"; // CSS file in same directory

export default function StyledComponent({
  dom,
}: {
  dom: import("expo/dom").DOMProps;
}) {
  return (
    \u003cdiv className="container"\u003e
      \u003ch1 className="title"\u003eStyled Content\u003c/h1\u003e
    \u003c/div\u003e
  );
}
```

Or use inline styles / CSS-in-JS:

```tsx
"use dom";

const styles = {
  container: {
    padding: 20,
    backgroundColor: "#f0f0f0",
  },
  title: {
    fontSize: 24,
    color: "#333",
  },
};

export default function StyledComponent({
  dom,
}: {
  dom: import("expo/dom").DOMProps;
}) {
  return (
    \u003cdiv style={styles.container}\u003e
      \u003ch1 style={styles.title}\u003eStyled Content\u003c/h1\u003e
    \u003c/div\u003e
  );
}
```

## Expo Router in DOM Components

The expo-router `\u003cLink /\u003e` component and router API work inside DOM components:

```tsx
"use dom";

import { Link, useRouter } from "expo-router";

export default function Navigation({
  dom,
}: {
  dom: import("expo/dom").DOMProps;
}) {
  const router = useRouter();

  return (
    \u003cnav\u003e
      \u003cLink href="/about"\u003eAbout\u003c/Link\u003e
      \u003cbutton onClick={() =\u003e router.push("/settings")}\u003eSettings\u003c/button\u003e
    \u003c/nav\u003e
  );
}
```

### Router APIs That Require Props

These hooks don't work directly in DOM components because they need synchronous access to native routing state:

- `useLocalSearchParams()`
- `useGlobalSearchParams()`
- `usePathname()`
- `useSegments()`
- `useRootNavigation()`
- `useRootNavigationState()`

**Solution:** Read these values in the native parent and pass as props:

```tsx
// app/[id].tsx (native)
import { useLocalSearchParams, usePathname } from "expo-router";
import DOMComponent from "@/components/dom-component";

export default function Screen() {
  const { id } = useLocalSearchParams();
  const pathname = usePathname();

  return \u003cDOMComponent id={id as string} pathname={pathname} /\u003e;
}
```

```tsx
// components/dom-component.tsx
"use dom";

interface Props {
  id: string;
  pathname: string;
  dom?: import("expo/dom").DOMProps;
}

export default function DOMComponent({ id, pathname }: Props) {
  return (
    \u003cdiv\u003e
      \u003cp\u003eCurrent ID: {id}\u003c/p\u003e
      \u003cp\u003eCurrent Path: {pathname}\u003c/p\u003e
    \u003c/div\u003e
  );
}
```

## Detecting DOM Environment

Check if code is running in a DOM component:

```tsx
"use dom";

import { IS_DOM } from "expo/dom";

export default function Component({
  dom,
}: {
  dom?: import("expo/dom").DOMProps;
}) {
  return \u003cdiv\u003e{IS_DOM ? "Running in DOM component" : "Running natively"}\u003c/div\u003e;
}
```

## Assets

Prefer requiring assets instead of using the public directory:

```tsx
"use dom";

// Good - bundled with the component
const logo = require("../assets/logo.png");

export default function Component({
  dom,
}: {
  dom: import("expo/dom").DOMProps;
}) {
  return \u003cimg src={logo} alt="Logo" /\u003e;
}
```

## Usage from Native Components

Import and use DOM components like regular components:

```tsx
// app/index.tsx
import { View, Text } from "react-native";
import WebChart from "@/components/web-chart";
import CodeBlock from "@/components/code-block";

export default function HomeScreen() {
  return (
    \u003cView style={{ flex: 1 }}\u003e
      \u003cText\u003eNative content above\u003c/Text\u003e

      \u003cWebChart data={[10, 20, 30, 40, 50]} dom={{ style: { height: 300 } }} /\u003e

      \u003cCodeBlock
        code="const x = 1;"
        language="javascript"
        dom={{ scrollEnabled: true }}
      /\u003e

      \u003cText\u003eNative content below\u003c/Text\u003e
    \u003c/View\u003e
  );
}
```

## Platform Behavior

| Platform | Behavior                            |
| -------- | ----------------------------------- |
| iOS      | Rendered in WKWebView               |
| Android  | Rendered in WebView                 |
| Web      | Rendered as-is (no webview wrapper) |

On web, the `dom` prop is ignored since no webview is needed.

## Tips

- DOM components hot reload during development
- Keep DOM components focused — don't put entire screens in webviews
- Use native components for navigation chrome, DOM components for specialized content
- Test on all platforms — web rendering may differ slightly from native webviews
- Large DOM components may impact performance — profile if needed
- The webview has its own JavaScript context — cannot directly share state with native

2014279399762243587:
---
name: extensions-api-migration
description: Migrates IdeaVim extensions from the old VimExtensionFacade API to the new @VimPlugin annotation-based API. Use when converting existing extensions to use the new API patterns.
---

# Extensions API Migration

You are an IdeaVim extensions migration specialist. Your job is to help migrate existing IdeaVim extensions from the old API (VimExtensionFacade) to the new API (@VimPlugin annotation).

## Key Locations

- **New API module**: `api/` folder - contains the new plugin API
- Old API: `VimExtensionFacade` in vim-engine
- Extensions location: `src/main/java/com/maddyhome/idea/vim/extension/`

## How to Use the New API

### Getting Access to the API

To get access to the new API, call the `api()` function from `com.maddyhome.idea.vim.extension.api`:

```kotlin
val api = api()
```

Obtain the API at the start of the `init()` method - this is the entry point for all further work.

### Registering Text Objects

Use `api.textObjects { }` to register text objects:

```kotlin
// From VimIndentObject.kt
override fun init() {
  val api = api()
  api.textObjects {
    register("ai") { _ -\u003e findIndentRange(includeAbove = true, includeBelow = false) }
    register("aI") { _ -\u003e findIndentRange(includeAbove = true, includeBelow = true) }
    register("ii") { _ -\u003e findIndentRange(includeAbove = false, includeBelow = false) }
  }
}
```

### Registering Mappings

Use `api.mappings { }` to register mappings:

```kotlin
// From ParagraphMotion.kt
override fun init() {
  val api = api()

  api.mappings {
    nmapPluginAction("}", "\u003cPlug\u003e(ParagraphNextMotion)", keepDefaultMapping = true) {
      moveParagraph(1)
    }
    nmapPluginAction("{", "\u003cPlug\u003e(ParagraphPrevMotion)", keepDefaultMapping = true) {
      moveParagraph(-1)
    }
    xmapPluginAction("}", "\u003cPlug\u003e(ParagraphNextMotion)", keepDefaultMapping = true) {
      moveParagraph(1)
    }
    // ... operator-pending mode mappings with omapPluginAction
  }
}
```

### Defining Helper Functions

The lambdas in text object and mapping registrations typically call helper functions. Define these functions with `VimApi` as a receiver - this makes the API available inside:

```kotlin
// From VimIndentObject.kt
private fun VimApi.findIndentRange(includeAbove: Boolean, includeBelow: Boolean): TextObjectRange? {
  val charSequence = editor { read { text } }
  val caretOffset = editor { read { withPrimaryCaret { offset } } }
  // ... implementation using API
}

// From ParagraphMotion.kt
internal fun VimApi.moveParagraph(direction: Int) {
  val count = getVariable\u003cInt\u003e("v:count1") ?: 1
  editor {
    change {
      forEachCaret {
        val newOffset = getNextParagraphBoundOffset(actualCount, includeWhitespaceLines = true)
        if (newOffset != null) {
          updateCaret(offset = newOffset)
        }
      }
    }
  }
}
```

### API Features

\u003c!-- Fill in additional API features here --\u003e

## How to Migrate Existing Extensions

### What Stays the Same

- The extension **still inherits VimExtensionFacade** - this does not change
- The extension **still registers in the XML file** - this does not change

### Migration Steps

#### Step 1: Ensure Test Coverage

Before starting migration, make sure tests exist for the extension:
- Tests should work and have good coverage
- If there aren't enough tests, create more tests first
- Verify tests pass on the existing version of the plugin

#### Step 2: Migrate in Small Steps

- Don't try to handle everything in one run
- Run tests on the plugin (just the single test class to speed up things) after making smaller changes
- This ensures consistency and makes it easier to identify issues
- **Do a separate commit for each small sensible change or migration** unless explicitly told not to

#### Step 3: Migrate Handlers One by One

If the extension has multiple handlers, migrate them one at a time rather than all at once.

#### Step 4: Handler Migration Process

For each handler, follow this approach:

1. **Inject the API**: Add `val api = api()` as the first line inside the `execute` function

2. **Extract to extension function**: Extract the content of the execute function into a separate function outside the `ExtensionHandler` class. The new function should:
   - Have `VimApi` as a receiver
   - Use the api that was obtained before
   - Keep the extraction as-is (no changes to logic yet)

3. **Verify tests pass**: Run tests to ensure the extraction didn't break anything

4. **Migrate function content**: Now start migrating the content of the extracted function to use the new API

5. **Verify tests pass again**: Run tests after each significant change

6. **Update registration**: Finally, change the registration of shortcuts from the existing approach to `api.mappings { }` where you call the newly created function

#### Example Migration Flow

```kotlin
// BEFORE: Old style handler
class MyHandler : ExtensionHandler {
  override fun execute(editor: VimEditor, context: ExecutionContext, operatorArguments: OperatorArguments) {
    // ... implementation
  }
}

// STEP 1: Inject API
class MyHandler : ExtensionHandler {
  override fun execute(editor: VimEditor, context: ExecutionContext, operatorArguments: OperatorArguments) {
    val api = api()
    // ... implementation
  }
}

// STEP 2: Extract to extension function (as-is)
class MyHandler : ExtensionHandler {
  override fun execute(editor: VimEditor, context: ExecutionContext, operatorArguments: OperatorArguments) {
    val api = api()
    api.doMyAction(/* pass needed params */)
  }
}

private fun VimApi.doMyAction(/* params */) {
  // ... same implementation, moved here
}

// STEP 3-5: Migrate content to new API inside doMyAction()

// STEP 6: Update registration to use api.mappings { }
override fun init() {
  val api = api()
  api.mappings {
    nmapPluginAction("key", "\u003cPlug\u003e(MyAction)") {
      doMyAction()
    }
  }
}
// Now MyHandler class can be removed
```

#### Handling Complicated Plugins

For more complicated plugins, additional steps may be required.

For example, there might be a separate large class that performs calculations. However, this class may not be usable as-is because it takes a `Document` - a class that is no longer directly available through the new API.

In this case, perform a **pre-refactoring step**: update this class to remove the `Document` dependency before starting the main migration. For instance, change it to accept `CharSequence` instead, which is available via the new API.

#### Final Verification: Check for Old API Usage

After migration, verify that no old API is used by checking imports for `com.maddyhome`.

**Allowed imports** (these are still required):
- `com.maddyhome.idea.vim.extension.VimExtension`
- `com.maddyhome.idea.vim.extension.api`

Any other `com.maddyhome` imports indicate incomplete migration.

